// REQUIRES: linux
// RUN: rm -rf %t.dir && mkdir %t.dir
// RUN: env python3 -c "import pathlib; target=pathlib.Path(r'%t.dir/input.js'); maybe='function maybeThrow(flag) { \\\"noinline\\\"; if (flag) throw new Error(\\\"boom\\\"); }\n'; outlined='function outlined(flag) { \\\"noinline\\\"; var retained = {answer: 42}; var value = {}; var number = 40;\n'+''.join('value.p%d = %d;\n' % (i, i) for i in range(100))+'gc(); maybeThrow(flag);\n'+''.join('value.p%d = %d;\n' % (i, i) for i in range(100, 200))+'return retained.answer + number + value.p199; }\n'; branch='function branched(flag) { \\\"noinline\\\"; var value = {}; if (flag) {\n'+''.join('value.q%d = %d;\n' % (i, i) for i in range(200))+'} return value; }\n'; loop='function looped(input) { \\\"noinline\\\"; var retained = {sum: 0}; var filler = {};\n'+''.join('filler.r%d = %d;\n' % (i, i) for i in range(200))+'for (var key in input) { gc(); retained.sum += input[key]; } return retained.sum; }\n'; with_try='function withTry(flag) { \\\"noinline\\\"; var value = {}; try {\n'+''.join('value.t%d = %d;\n' % (i, i) for i in range(200))+'if (flag) throw new Error(\\\"caught\\\"); } catch (error) { value.caught = true; } return value; }\n'; complex_cfg='function complex(value) { \\\"noinline\\\"; var result = -1;\n'+''.join('if (value === %d) result = %d;\n' % (i, i) for i in range(1100))+'return result; }\n'; main='print(outlined(false)); try { outlined(true); } catch (error) { print(error.message); } print(\\\"after\\\"); print(branched(true).q199); print(branched(false).q199 === undefined); print(looped({a: 2, b: 3})); print(looped({})); print(withTry(false).t199); print(withTry(true).caught); print(complex(1099));\n'; target.write_text(maybe+outlined+branch+loop+with_try+complex_cfg+main)"
// RUN: cd %t.dir && %shermes -O -emit-c -Xemit-c-bundle -Xemit-c-shard-size=65536 -exported-unit=outline -o unit.c.json input.js
// RUN: cd %t.dir && env python3 -c "import json; raw=open('unit.c.json').read(); assert '\\\"cOptimizationLevel\\\":0,\\\"firstFunctionId\\\":' in raw and raw == json.dumps(json.loads(raw), separators=(',', ':'), sort_keys=True) + '\\n'"
// RUN: cd %t.dir && env python3 -c "import json,pathlib,re; manifest=json.load(open('unit.c.json')); units=manifest['translationUnits']; function_units=[unit for unit in units if unit['role']=='function']; sources={unit['path']:pathlib.Path(unit['path']).read_text() for unit in function_units}; part_files={path:source for path,source in sources.items() if re.search(r'void sh_outline_f_[0-9]+_part_[0-9]+\\([^)]*\\) \\{',source)}; ids={int(match) for source in part_files.values() for match in re.findall(r'void sh_outline_f_([0-9]+)_part_[0-9]+',source)}; fragments=[unit for unit in function_units if 'functionFragmentCount' in unit]; fragment_ids={unit['firstFunctionId'] for unit in fragments}; wrappers=[sources[unit['path']] for unit in fragments if unit['functionFragmentIndex'] == 0]; o0_units=[unit for unit in function_units if unit.get('cOptimizationLevel') == 0]; assert len(part_files) >= 2 and len(ids) >= 2 and ids == fragment_ids; assert all('_sh_enter(' not in source and '_sh_leave(' not in source and 'SH_ATTRIBUTE_NOINLINE' in source and 'tryState' not in source and 'jmpBuf' not in source for source in part_files.values()); assert any('goto L' in source for source in wrappers); assert any('SHJmpBuf jmpBuf' in source and 'L_catch:' in source for source in wrappers); assert len(o0_units) == 1 and o0_units[0]['functionCount'] == 1 and 'functionFragmentCount' not in o0_units[0] and o0_units[0]['oversize'] and o0_units[0]['oversizeReason'] == 'no-outlineable-run'; assert all(not unit['oversize'] and 'oversizeReason' not in unit for unit in fragments); assert all(not unit.get('oversize') or unit is o0_units[0] for unit in function_units); assert all((lambda group: group[0]['functionFragmentCount'] == len(group) and {unit['functionFragmentIndex'] for unit in group} == set(range(len(group))) and all(unit['functionFragmentCount'] == len(group) and unit['firstFunctionId'] == function_id and unit['lastFunctionId'] == function_id for unit in group))([unit for unit in fragments if unit['firstFunctionId'] == function_id]) for function_id in fragment_ids)"
// RUN: cd %t.dir && env python3 -c "import json; units=json.load(open('unit.c.json'))['translationUnits']; fragment_ids={unit['firstFunctionId'] for unit in units if 'functionFragmentCount' in unit}; groups={function_id:[index for index,unit in enumerate(units) if unit.get('firstFunctionId') == function_id and 'functionFragmentCount' in unit] for function_id in fragment_ids}; assert all(indexes == list(range(indexes[0], indexes[0] + len(indexes))) for indexes in groups.values())"
// RUN: env python3 -c "import pathlib; target=pathlib.Path(r'%t.dir/initializers.js'); count=1500; target.write_text(''.join('var closure%d = function closure%d() { return %d; };\\nvar class%d = class Class%d {};\\n' % (i, i, i, i, i) for i in range(count)) + 'print(typeof closure1499, typeof class1499);\\n')"
// RUN: cd %t.dir && %shermes -O -emit-c -Xemit-c-bundle -Xemit-c-shard-size=65536 -exported-unit=initializers -o initializers.c.json initializers.js
// RUN: cd %t.dir && env python3 -c "import json,pathlib,re; target=65536; manifest=json.load(open('initializers.c.json')); fragments=[unit for unit in manifest['translationUnits'] if unit['role']=='function' and unit.get('firstFunctionId') == 0 and 'functionFragmentCount' in unit]; assert len(fragments) > 1; assert fragments[0]['functionFragmentCount'] == len(fragments); assert {unit['functionFragmentIndex'] for unit in fragments} == set(range(len(fragments))); assert all(unit['functionCount'] == 1 and unit['lastFunctionId'] == 0 and not unit.get('oversize', False) and unit['size'] <= target for unit in fragments); sources=[pathlib.Path(unit['path']).read_text() for unit in fragments]; assert sum(source.count('_sh_ljs_create_closure') + source.count('_sh_ljs_create_class') for source in sources) >= 2 * 1500; assert any(re.search(r'void sh_initializers_f_0_part_[0-9]+\\(', source) for source in sources)"
// RUN: env python3 -c "import pathlib; target=pathlib.Path(r'%t.dir/single.js'); target.write_text('function single() { \\\"noinline\\\"; var object = {};\n'+''.join('object.p%d = %d;\n' % (i, i) for i in range(100))+'return object; }\nprint(single().p99);\n')"
// RUN: cd %t.dir && %shermes -O -emit-c -Xemit-c-bundle -Xemit-c-shard-size=1 -exported-unit=single -o single.c.json single.js
// RUN: cd %t.dir && env python3 -c "import json; units=json.load(open('single.c.json'))['translationUnits']; groups={function_id:[unit for unit in units if unit.get('firstFunctionId') == function_id and 'functionFragmentCount' in unit] for function_id in {unit['firstFunctionId'] for unit in units if 'functionFragmentCount' in unit}}; assert any(len(group) > 1 and all(unit['oversize'] and unit['oversizeReason'] == 'single-instruction' for unit in group) for group in groups.values())"
// RUN: env python3 -c "import pathlib; target=pathlib.Path(r'%t.dir/invariant.js'); linear='function mixed(value) { \\\"noinline\\\"; var object = {};\n'+''.join('object.p%d = %d;\n' % (i, i) for i in range(64)); cfg=''.join('if (value === %d) object.q%d = %d;\n' % (i, i, i) for i in range(1100)); target.write_text(linear+cfg+'return object; }\nprint(mixed(1099).q1099);\n')"
// RUN: cd %t.dir && (! %shermes -O -emit-c -Xemit-c-bundle -Xemit-c-shard-size=65536 -exported-unit=invariant -o invariant.c.json invariant.js 2>&1) | %FileCheck --check-prefix=INVARIANT %s
// RUN: cd %t.dir && test ! -e invariant.c.json
// RUN: env python3 -c "import pathlib; pathlib.Path(r'%t.dir/initializers-main.c').write_text('#include \"hermes/VM/static_h.h\"\\n\\ntypedef struct SHConsoleContext SHConsoleContext;\\n\\nSHConsoleContext *init_console_bindings(SHRuntime *shr, int scriptArgc, const char *const *scriptArgv);\\nvoid free_console_context(SHConsoleContext *consoleContext);\\nbool run_event_loop(SHRuntime *shr, SHConsoleContext *consoleContext);\\nextern SHUnit *sh_export_initializers(void);\\n\\nint main(void) {\\n  SHRuntime *shr = _sh_init(0, NULL);\\n  SHConsoleContext *consoleContext = init_console_bindings(shr, 0, NULL);\\n  bool success = _sh_initialize_units(shr, 1, sh_export_initializers) && run_event_loop(shr, consoleContext);\\n  free_console_context(consoleContext);\\n  _sh_done(shr);\\n  return success ? 0 : 1;\\n}\\n')"
